const listProducts = `-- name: ListProducts :many
SELECT p.id, p.brand, p.name, p.model_year, p.category, p.status, p.option_names, p.created_at,
       p.model_key, p.split_values, p.description_html, p.image_urls, coalesce(l.wanted, false)::bool AS wanted
FROM product p
LEFT JOIN shopify_listing l ON l.product_id = p.id
WHERE ($1::text = '' OR p.status = $1::text)
  AND (NOT $2::bool
       OR EXISTS (SELECT 1 FROM variant v WHERE v.product_id = p.id AND v.price_cents IS NULL))
  AND ($3::text = ''
       OR strpos(lower(p.brand || ' ' || p.name), lower($3::text)) > 0
       OR EXISTS (SELECT 1 FROM variant v
                  LEFT JOIN variant_supplier_item vs ON vs.variant_id = v.id
                  LEFT JOIN supplier_item s ON s.id = vs.supplier_item_id
                  WHERE v.product_id = p.id
                    AND strpos(lower(v.sku || ' ' || v.ean || ' ' || coalesce(s.sku, '')), lower($3::text)) > 0))
ORDER BY p.brand, p.model_key, p.id
LIMIT $4
`

type ListProductsParams struct {
	Status   string
	Unpriced bool
	Q        string
	MaxRows  int32
}

type ListProductsRow struct {
	ID              int64
	Brand           string
	Name            string
	ModelYear       *int32
	Category        string
	Status          string
	OptionNames     []byte
	CreatedAt       time.Time
	ModelKey        string
	SplitValues     []byte
	DescriptionHtml string
	ImageUrls       []byte
	Wanted          bool
}

// status ” means all; unpriced limits to products with a variant without
// sales price; q matches brand, name, own and supplier article numbers, EANs.
func (q *Queries) ListProducts(ctx context.Context, arg ListProductsParams) ([]ListProductsRow, error) {
	rows, err := q.db.Query(ctx, listProducts,
		arg.Status,
		arg.Unpriced,
		arg.Q,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListProductsRow
	for rows.Next() {
		var i ListProductsRow
		if err := rows.Scan(
			&i.ID,
			&i.Brand,
			&i.Name,
			&i.ModelYear,
			&i.Category,
			&i.Status,
			&i.OptionNames,
			&i.CreatedAt,
			&i.ModelKey,
			&i.SplitValues,
			&i.DescriptionHtml,
			&i.ImageUrls,
			&i.Wanted,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

